      <div id="planet-survey" class="orbit-context" role="dialog" tabindex="-1" aria-labelledby="orbit-planet-title" hidden>
        <div class="survey-scroll"><div id="planet-build" class="map-preview"><div class="planet-build-content"></div></div><div id="dock-inspection" role="region" aria-labelledby="inspection-title" hidden></div></div>
      </div>
